import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { cp, mkdir, mkdtemp, readFile, writeFile } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { createHash } from 'node:crypto';
import { prepareV2Profile } from './prepare-v2-profile.mjs';
const repo = resolve(import.meta.dirname, '..');
const app = join(repo, 'release/v2-home-alpha7/mac-arm64/CanvasTTY 2.0 Alpha.app');
const binary = join(app, 'Contents/MacOS/CanvasTTY 2.0 Alpha');
await mkdir(join(repo, '../acceptance'), { recursive: true });
const output = await mkdtemp(join(repo, '../acceptance/alpha7-'));
const profile = join(output, 'profile');
await prepareV2Profile(profile);
await mkdir(join(output, 'media'));
await cp(join(repo, 'tests/fixtures/live-skins/background.mp4'), join(output, 'media/movie.mp4'));
await cp(join(repo, 'resources/home/avatar-ai-v1.gif'), join(output, 'media/animation.gif'));
const audio = spawnSync('ffmpeg', ['-loglevel','error','-f','lavfi','-i','sine=frequency=440:duration=2','-c:a','libmp3lame',join(output,'media/song.mp3')], { encoding: 'utf8' });
assert.equal(audio.status, 0, audio.stderr);
const env = { ...process.env, CANVASTTY_USER_DATA_DIR: profile, CANVASTTY_HOME_LAB_SMOKE_OUTPUT: output, CANVASTTY_V2_LAB_SMOKE: process.argv.includes('--skip-duo') ? '0' : '1' };
env.CANVASTTY_CORE_FILES_LAB = '1';
for (const key of Object.keys(env)) if (key.startsWith('CANVASTTY_RUNTIME_') || key.startsWith('CANVASTTY_SHELL_') || key.startsWith('CANVASTTY_CAPTURE_') || key.startsWith('CANVASTTY_MAC_WINDOW_LAB') || key.startsWith('CANVASTTY_DUO_LAB_')) delete env[key];
delete env.ELECTRON_RUN_AS_NODE;
console.log('Alpha7 acceptance artifacts: ' + output);
const child = spawnSync(binary, [], { env, encoding: 'utf8', timeout: 120_000, killSignal: 'SIGKILL', maxBuffer: 4 * 1024 * 1024 });
await writeFile(join(output, 'app.log'), (child.stdout ?? '') + (child.stderr ?? ''));
if (child.error) throw child.error;
assert.equal(child.status, 0, 'Packaged acceptance failed; see ' + join(output, 'app.log'));
const report = JSON.parse(await readFile(join(output, 'verification.json'), 'utf8'));
assert.equal(report.version, '2.0.0-alpha.7'); assert.equal(report.packaged, true); assert.equal(report.profile, profile);
const code = `const pty=require(process.argv[1]);const term=pty.spawn('/bin/zsh',['-f','-c','printf ALPHA7_PTY_OK'],{name:'xterm-color',cols:80,rows:24,cwd:process.cwd(),env:{PATH:'/usr/bin:/bin'}});let out='';term.onData(d=>out+=d);term.onExit(e=>{if(e.exitCode!==0||!out.includes('ALPHA7_PTY_OK'))process.exit(1);console.log('ALPHA7_PTY_OK')});setTimeout(()=>process.exit(2),10000).unref();`;
const pty = spawnSync(binary, ['-e', code, join(app, 'Contents/Resources/app.asar/node_modules/node-pty')], { env: { ...env, ELECTRON_RUN_AS_NODE: '1' }, encoding: 'utf8', timeout: 15_000 });
await writeFile(join(output, 'pty.log'), (pty.stdout ?? '') + (pty.stderr ?? ''));
assert.equal(pty.status, 0); assert.match(pty.stdout, /ALPHA7_PTY_OK/);
const signature = spawnSync('codesign', ['--verify', '--deep', '--strict', app], { encoding: 'utf8', timeout: 15_000 });
assert.equal(signature.status, 0, signature.stderr);
Object.assign(report, { packagedPty: 'passed', signature: 'ad-hoc verified', appBundle: app, asarSha256: createHash('sha256').update(await readFile(join(app, 'Contents/Resources/app.asar'))).digest('hex') });
await writeFile(join(output, 'verification.json'), JSON.stringify(report, null, 2));
await writeFile(join(repo, '../logs/alpha7-latest-acceptance.json'), JSON.stringify({ output, ...report }, null, 2));
console.log(JSON.stringify({ output, version: report.version, checks: report.checks, geometry: report.geometry.length, asarSha256: report.asarSha256 }));
